	@Test
	void contextFilteringAndContinuationPagesKeepQuadMultiplicity() {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			connection.begin();
			connection.clear();
			IRI s = vf.createIRI(EX + "root");
			IRI p = vf.createIRI(EX + "p");
			for (int i = 0; i < 3_000; i++) {
				var o = i % 2 == 0 ? vf.createIRI(EX + i) : vf.createLiteral(i);
				connection.add(s, p, o, vf.createIRI(EX + "g1"), vf.createIRI(EX + "g2"));
				if (i % 3 == 0) {
					connection.add(s, p, o);
				}
			}
			connection.add(s, p, vf.createLiteral("value", "en"), vf.createIRI(EX + "g1"));
			connection.add(s, p, vf.createLiteral("value", "EN"), vf.createIRI(EX + "g2"));
			connection.commit();
		}
		assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
		assertParity(CENSUS);
		assertParity("SELECT ?g (COUNT(*) AS ?quads) (COUNT(DISTINCT ?o) AS ?objects) "
				+ "(SUM(IF(isLiteral(?o), 1, 0)) AS ?literals) WHERE { GRAPH ?g { ?s ?p ?o } } GROUP BY ?g");
	}

	@Test
	void incompleteAndDisabledAdjacencyDeclineWithoutPartialResults() {
		for (DirectAdjacencyMode mode : List.of(DirectAdjacencyMode.PREFER, DirectAdjacencyMode.DISABLED)) {
			repository.shutDown();
			LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setDirectAdjacencyMode(mode);
			config.setDirectAdjacencyCoverage(DirectAdjacencyCoverage.SELECTED);
			config.setDirectAdjacencyPredicates(List.of(store.getValueFactory().createIRI(EX + "p1")));
			store = new LmdbStore(dataDir, config);
			repository = new SailRepository(store);
			repository.init();
			if (mode != DirectAdjacencyMode.DISABLED) {
				assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
			}
			assertParity(CENSUS);
			assertThat(telemetry(CENSUS)).doesNotContain("nativeExecutionPath=adjacencyCensus");
		}
	}

